/* syTaskmanCheckBufferLengths' two `while (TRUE);` spins, replaced by recovery
 * under SSB64_TARGET_NDS. All four must read 0; see the long note beside their
 * definitions in src/port/diagnostics.c. */
extern volatile u32 gNdsTaskmanDLOverflowCount;
extern volatile u32 gNdsTaskmanDLOverflowKind;
extern volatile u32 gNdsTaskmanDLOverflowBytes;
extern volatile u32 gNdsTaskmanGraphicsOverflowCount;
extern volatile u32 gNdsTaskmanGraphicsOverflowBytes;
/* objman.c's NINETEEN `while (TRUE);` spins, same treatment. Every one is an
 * exhausted object pool (GObj/GObjProcess/GObjThread/DObj/MObj/AObj/XObj/SObj/
 * CObj) or a broken stack link, and every one of them is a dead handheld on a
 * target with no debugger attached. Converting syTaskmanCheckBufferLengths
 * alone left these reachable, which is why "the match froze" kept coming back.
 * Count must read 0; the mask names WHICH site, numbered in source order, so a
 * freeze report becomes "pool N is short" instead of a bisect. */
extern volatile u32 gNdsObjmanPanicCount;
extern volatile u32 gNdsObjmanPanicMask;
/* The same freeze class one level down, in the animation-script parsers rather
 * than the allocators. objman's nineteen spins were literal `while (TRUE);`;
 * these four are `do { ... } while (anim_wait <= 0.0F);` loops that walk asset
 * data and terminate only when the data is well formed. Three captures on
 * 2026-08-02/03 stopped in the first of them on a script pointer of 0x23842ea,
 * which is 2 mod 4 and so cannot be an AObjEvent32*.
 *
 * Count must read 0. Mask bit: 0/1 gcParseDObjAnimJoint (bad opcode / event
 * limit), 2/3 gcParseMObjMatAnimJoint, 4/5 gcParseCObjCamAnimJoint, 6/7
 * ftAnimParseDObjFigatree. Script and Opcode are the last fault's data, so a
 * report names the stream instead of needing a bisect. */
extern volatile u32 gNdsObjAnimRunawayCount;
extern volatile u32 gNdsObjAnimRunawayMask;
extern volatile u32 gNdsObjAnimRunawayScript;
extern volatile u32 gNdsObjAnimRunawayOpcode;
/* lbCommonAddDObjAnimJointAll (decomp lb/lbcommon.c:785). Two callers are live
 * in P1: the shield, ft/ftcommon/ftcommonguard1.c:277, in the same breath as
 * fp->anim_desc.flags.is_anim_joint = TRUE -- which is why the counters carry
 * its name -- and Fox's entry Arwing, ef/efmanager.c:5734/5736. Engagement for
 * both arms of the 2026-08-13 fix: the stub it replaced incremented Calls and
 * nothing else, so a zero here means no caller ran rather than "the install did
 * nothing". Attach + Null equals the joints walked. */
extern volatile u32 gNdsShieldAnimJointInstallCalls;
extern volatile u32 gNdsShieldAnimJointAttachCount;
extern volatile u32 gNdsShieldAnimJointNullCount;
extern volatile u32 gNdsStartupTaskmanMallocCount;
