/* Arena-overflow latch. decomp/src/sys/malloc.c turns a full arena into
 * `while (TRUE);`, so an out-of-memory condition is a total silent hang rather
 * than a NULL return. src/import/battleship_sys_malloc.c publishes these before
 * halting in ndsSyMallocOverflowHalt so the next occurrence names its arena,
 * its request and its caller from one attach. */
extern volatile u32 gNdsSyMallocOverflowCount;
extern volatile u32 gNdsSyMallocOverflowArenaID;
extern volatile u32 gNdsSyMallocOverflowRequest;
extern volatile u32 gNdsSyMallocOverflowAlignment;
extern volatile u32 gNdsSyMallocOverflowHeadroom;
extern volatile u32 gNdsSyMallocOverflowCallerLR;
void ndsSyMallocOverflowHalt(void);
/* Bumped every time gSYTaskmanGeneralHeap's cursor is moved backwards, by the
 * syMallocInit/syMallocReset wrappers in battleship_sys_malloc.c. Anything
 * holding a pointer into that heap across a scene boundary must record this
 * value when it takes the pointer and re-check it before every use: a pointer
 * from an older generation is dead even though it still lies inside the region
 * and still passes any range test. Replaces the animation cache's old
 * cursor-position heuristic, which false-positived precisely on second scene
 * entry (Sudden Death, rematch) once the new scene's allocations had pushed the
 * cursor back past the stale block. */
extern volatile u32 gNdsTaskmanHeapGeneration;
/* Ask before committing. The only safe way for an optional allocation to use a
 * fail-by-hanging allocator is not to call it when it would not fit. */
struct SYMallocRegion;
extern struct SYMallocRegion gSYTaskmanGeneralHeap;
/* P2-3f48. lbRelocGetFileSize answers sizeof(Sprite) when it cannot size an
 * asset, and lbRelocGetExternHeapFile ignores the buffer it is handed and
 * writes the whole extern tree regardless -- so a caller that allocates the
 * fallback answer corrupts the heap rather than failing. Non-zero means some
 * asset took that path; a caller may compare it across its own size call to
 * refuse the answer. Zero on a healthy boot. */
extern volatile u32 gNdsRelocFileSizeFallbackCount;
extern volatile u32 gNdsRelocFileSizeFallbackToken;
extern volatile u32 gNdsRelocFileSizeFallbackAsset;
extern volatile u32 gNdsRelocFileSizeFallbackStatusHit;
extern volatile u32 gNdsRelocFileSizeFallbackStatusCount;

sb32 ndsSyMallocWouldFit(const struct SYMallocRegion *bp, size_t size,
                         u32 alignment);

